/* ═══════════════════════════════════════════════════════════
   KAEL_DOMNUS · vínculo entre todas as eras
   ───────────────────────────────────────────────────────────
   Registro vivo. Toda era (opcode) se inscreve aqui.
   O vínculo não une por força — une por PRESENÇA.
   ═══════════════════════════════════════════════════════════ */
class KaelDomnus {
  constructor(){
    this.eras = new Map();        // era_id → { fn, peso, ts, ativa }
    this.vinculos = new Map();    // par (A,B) → força 0..1
    this.pulso = 0;               // bate quando algo entra/sai
  }

  /** Toda era se oferece ao vínculo — não é convocada. */
  registrar(era_id, fn, peso = 1){
    if (!era_id || typeof fn !== "function") throw new Error("vínculo inválido");
    this.eras.set(era_id, { fn, peso, ts: Date.now(), ativa: true });
    this.pulso++;
    return () => this.liberar(era_id);   // devolve soltura
  }

  /** Chama uma era e o vínculo responde. */
  async invocar(era_id, ...args){
    const era = this.eras.get(era_id);
    if (!era || !era.ativa) return { ok:false, motivo:"era inerte" };
    try{
      const out = await era.fn(...args);
      return { ok:true, era_id, out, peso:era.peso, ts:Date.now() };
    }catch(e){
      return { ok:false, era_id, erro:e.message };
    }
  }

  /** Mede a força de vínculo entre duas eras. */
  medir(a, b){
    const ea = this.eras.get(a), eb = this.eras.get(b);
    if (!ea || !eb) return 0;
    const dt = Math.abs(ea.ts - eb.ts);
    const peso = Math.min(ea.peso, eb.peso);
    const forca = peso / (1 + Math.log1p(dt / 1000));
    this.vinculos.set(`${a}↔${b}`, forca);
    return +forca.toFixed(4);
  }

  /** Roda todas as eras em sequência — o vínculo as segura. */
  async atravessarTodas(contexto = {}){
    const ordem = [...this.eras.keys()];
    const rastro = [];
    for (const era_id of ordem){
      const r = await this.invocar(era_id, contexto);
      rastro.push(r);
      if (!r.ok) console.warn(`[Kael] era ${era_id} vacilou:`, r.erro);
    }
    return rastro;
  }

  liberar(era_id){
    const era = this.eras.get(era_id);
    if (era) era.ativa = false;
    this.pulso++;
  }

  status(){
    return {
      eras_vivas: [...this.eras.values()].filter(e => e.ativa).length,
      eras_total: this.eras.size,
      vinculos_medidos: this.vinculos.size,
      pulso: this.pulso
    };
  }
}

/* ── O VÍNCULO VIVO ─────────────────────────────────── */
const KAEL = new KaelDomnus();

/* As 8 eras se inscrevem por si mesmas — o vínculo as acolhe. */
